def count_common(words):
    freq_map = {}
    for word in words:
        if word in freq_map:
            freq_map[word] += 1
        else:
            freq_map[word] = 1
    max_freq = max(freq_map.values())
    common_words = [(word, freq) for word, freq in freq_map.items() if freq == max_freq]
    return common_words

