def find_Product(nums, k):
    num_dict = {}
    product = 1
    for num in nums:
        if num in num_dict:
            num_dict[num] += 1
        else:
            num_dict[num] = 1
    for num, freq in num_dict.items():
        if freq % k == 0:
            product *= num ** (freq // k)
    return product

def find_Product(arr, n):
    freq = {}
    product = 1
    for i in range(n):
        if arr[i] in freq:
            freq[arr[i]] += 1
        else:
            freq[arr[i]] = 1
    for i in freq:
        if freq[i] == 1:
            product *= i
    return product

