def comb_sort(lst):
    n = len(lst)
    gap = n
    swapped = True

    while gap > 1 and swapped:
        gap = int(gap / 1.3)
        if gap < 1:
            gap = 1
        swapped = False
        i = 0
        while i + gap < n:
            if lst[i] > lst[i + gap]:
                lst[i], lst[i + gap] = lst[i + gap], lst[i]
                swapped = True
            i += 1
    return lst

