def find_longest_repeating_subseq(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]
    ans = 0
    for i in range(n):
        dp[i][i] = 1
        for j in range(i + 1, n):
            if s[i] == s[j]:
                dp[i][j] = 2 + dp[i + 1][j - 1]
                ans = max(ans, dp[i][j])
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])
    return ans

def find_longest_repeating_subseq(s):
    n = len(s)
    count = [[0 for x in range(n+1)] for x in range(n+1)]
    for i in range(n+1):
        for j in range(n+1):
            if (i == 0 or j == 0):
                count[i][j] = 0
            elif (s[i-1] == s[j-1] and i != j):
                count[i][j] = (count[i-1][j-1] + 1)
            else:
                count[i][j] = max(count[i-1][j], count[i][j-1])
    return count[n][n]

