        return 2
    elif n == 1:
        return 2
    elif n == 2:
        return 5
    elif n == 3:
        return 17
    else:
        primes = [2, 5, 17]
        for i in range(4, n + 1):
            smallest_prime = 1
            for prime in primes:
                if prime > i ** 0.5:
                    break
                if i % prime == 0:
                    smallest_prime = prime
            primes.append(i if smallest_prime == i else smallest_prime * 2)
        return primes[n - 1]

def newman_prime(n):
