    flipped = False
    flips = 0
    for i in range(len(binary_string)):
        if binary_string[i] == '0' and not flipped:
            flipped = True
            flips += 1
        elif binary_string[i] == '1' and flipped:
            flipped = False
            flips += 1
    return flips

