def remove_replica(input_tuple):
    from collections import OrderedDict
    from itertools import groupby
    from operator import itemgetter

    def key_func(x):
        return (x, x)

    dict_ = OrderedDict.fromkeys(input_tuple, 0)
    new_list = [k for k, g in groupby(sorted(dict_.items()), key_func)]
    new_tuple = tuple(new_list)

    for i in range(len(new_tuple)):
        if new_tuple[i] in input_tuple:
            count = input_tuple.count(new_tuple[i])
            if count > 1:
                new_tuple = new_tuple[:i] + (new_tuple[i],) + new_tuple[i+1:]

    return new_tuple

