def find_rotation_count(nums):
    def is_rotated(a, b):
        return a > b

    def binary_search(nums, target):
        low, high = 0, len(nums) - 1
        while low <= high:
            mid = (low + high) // 2
            if nums[mid] == target:
                return mid
            elif is_rotated(nums[low], nums[mid]):
                if is_rotated(target, nums[low]):
                    high = mid - 1
                else:
                    low = mid + 1
            else:
                if is_rotated(nums[mid], target):
                    low = mid + 1
                else:
                    high = mid - 1
        return -1

    def is_sorted(nums):
        return all(nums[i] <= nums[i + 1] for i in range(len(nums) - 1))

    if is_sorted(nums):
        return 0
    elif binary_search(nums, nums[0]) != -1:
        return 1
    else:
        return 2

