def median_trapezium(a, b, c):
    s = (a + b + c) / 2
    return s * (s - a) * (s - b) * (s - c) ** 0.5

def median_trapezium(a, b, c):
    p = (a + b + c) / 2
    m = max(a, b, c)
    return (p * (p - a) * (p - b) * (p - c)) ** 0.5 + m * ((p * (p - a) * (p - b)) / ((p - m) * (p - m - 1))) + m * ((p * (p - c) * (p - c - 1)) / ((p - m) * (p - m - 1))) - m * ((p * (p - a) * (p - b)) / ((p - m) * (p - m - 1)))

